//! Hash-pinned fixture sets whose signature members no code verifies.
//!
//! The internet-of-agents web3 evidence console bundle is pinned by the
//! SHA-256 digests in its `bundle-manifest.json`; the app and its end-to-end
//! tests compare digests only. This check fails when any other file starts
//! reading the bundle or when the app gains a signature verifier, because the
//! bundle's signatures are not wrapper-signed and must then be regenerated by
//! an owning generator instead.

use std::path::Path;
use std::process::Command;

use crate::XtaskError;

pub(crate) const WEB3_GOOD_BUNDLE: &str =
    "examples/internet-of-agents-web3-network/app/tests/fixtures/good-bundle";

/// Files allowed to name the bundle: digest-only readers, the digest stamper,
/// documentation of how to serve it, and the fixture gate.
const WEB3_GOOD_BUNDLE_READERS: &[&str] = &[
    "docs/superpowers/plans/2026-10-20-m1-item1-signing-wrapper.md",
    "examples/internet-of-agents-web3-network/README.md",
    "examples/internet-of-agents-web3-network/app/README.md",
    "examples/internet-of-agents-web3-network/app/playwright.config.ts",
    "examples/internet-of-agents-web3-network/app/scripts/stamp-fixture-hashes.mjs",
    "examples/internet-of-agents-web3-network/app/tests/e2e/failclosed.spec.ts",
    "examples/internet-of-agents-web3-network/app/tests/e2e/verdict.spec.ts",
    "xtask/src/hash_pinned.rs",
    "xtask/src/signed_fixtures.rs",
];

/// The app code that serves the bundle.
const WEB3_APP_SOURCES: &[&str] = &[
    "examples/internet-of-agents-web3-network/app/app",
    "examples/internet-of-agents-web3-network/app/components",
    "examples/internet-of-agents-web3-network/app/lib",
];

/// Signature verification primitives the app must not apply to the bundle.
const SIGNATURE_VERIFIER_PATTERN: &str =
    r"ed25519|nacl|@noble|chio-ts|@chio/|verifyAsync|subtle\.verify|verify_signature|verifySignature";

/// `git grep -l -F good-bundle` lists only [`WEB3_GOOD_BUNDLE_READERS`]
/// outside the bundle, and `git grep -l -i -E` [`SIGNATURE_VERIFIER_PATTERN`]
/// over [`WEB3_APP_SOURCES`] lists nothing.
pub(crate) fn check_web3_good_bundle_unverified(root: &Path) -> Result<(), XtaskError> {
    let bundle_prefix = format!("{WEB3_GOOD_BUNDLE}/");
    let unexpected: Vec<String> = git_grep(root, &["-l", "-F", "good-bundle"])?
        .into_iter()
        .filter(|path| {
            !path.starts_with(&bundle_prefix) && !WEB3_GOOD_BUNDLE_READERS.contains(&path.as_str())
        })
        .collect();
    if !unexpected.is_empty() {
        return Err(XtaskError::Validation(format!(
            "{WEB3_GOOD_BUNDLE} is hash-pinned and not wrapper-signed; new readers need an owning generator: {unexpected:?}"
        )));
    }
    let mut args = vec!["-l", "-i", "-E", SIGNATURE_VERIFIER_PATTERN, "--"];
    args.extend_from_slice(WEB3_APP_SOURCES);
    let verifiers = git_grep(root, &args)?;
    if !verifiers.is_empty() {
        return Err(XtaskError::Validation(format!(
            "the web3 evidence console references signature verification ({verifiers:?}); {WEB3_GOOD_BUNDLE} needs an owning generator"
        )));
    }
    Ok(())
}

/// Paths `git grep` prints; exit status 1 means no match.
fn git_grep(root: &Path, args: &[&str]) -> Result<Vec<String>, XtaskError> {
    let output = Command::new("git")
        .arg("grep")
        .args(args)
        .current_dir(root)
        .output()
        .map_err(|err| XtaskError::Io("git grep".to_owned(), err))?;
    match output.status.code() {
        Some(0) => Ok(String::from_utf8_lossy(&output.stdout)
            .lines()
            .map(str::to_owned)
            .collect()),
        Some(1) => Ok(Vec::new()),
        _ => Err(XtaskError::Process(format!(
            "git grep {args:?} failed: {}",
            String::from_utf8_lossy(&output.stderr)
        ))),
    }
}

#[cfg(test)]
mod tests {
    use super::check_web3_good_bundle_unverified;

    #[test]
    fn web3_good_bundle_has_no_signature_reader() {
        let root = crate::workspace_root().unwrap_or_else(|err| panic!("{err}"));
        check_web3_good_bundle_unverified(&root).unwrap_or_else(|err| panic!("{err}"));
    }
}
